namespace generic.jar;









public class JarEntryRootNode : JarEntryNode {
	private JarFile jarFile;
	private File file;

	public JarEntryRootNode(File file, JarEntryFilter filter)
    : base(null, "")
    {
		jarFile = new JarFile(file);
		this.file = file;
		if (filter == null) {
			filter = new DefaultFilter();
		}
		createIndex(filter);
	}

	/* @Override */
	protected JarFile getJarFile() {
		return jarFile;
	}

	protected File getFile() {
		return file;
	}

	public URL toURL()
    {
		return file.toURI().toURL();
	}

	private void createIndex(JarEntryFilter filter) {
		Enumeration<JarEntry> entries = jarFile.entries();
		while (entries.hasMoreElements()) {
			JarEntry jarEntry = entries.nextElement();
			if (jarEntry.isDirectory()) {
				continue;
			}
			if (filter.accepts(jarEntry)) {
				addFile(jarEntry.getName());
			}
		}

	}

	private void addFile(string path) {
		string[] split = path.split("/");
		JarEntryNode node = this;
		foreach (string @string in split) {
			node = getOrCreateNode(node, @string);
		}
	}

	private JarEntryNode getOrCreateNode(JarEntryNode node, string name) {
		return node.createNode(name);  // if already exists, create will return exiting node
	}

	private static class DefaultFilter : JarEntryFilter {

		/* @Override */
		public bool accepts(JarEntry jarEntry) {
			string name = jarEntry.getName();
			if (name.endsWith(".class")) {
				return false;
			}
			if (name.endsWith(".png")) {
				return false;
			}
			if (name.endsWith(".gif")) {
				return false;
			}
			return true;
		}

	}
}
